import java.util.*;
public class BinarySearchTree<E extends Comparable<E>> { static class Node<E>{E key;Node<E> left,right;Node(E k){key=k;}} Node<E> root; public void insert(E k){root=insert(root,k);} private Node<E> insert(Node<E> n,E k){if(n==null)return new Node<E>(k);int c=k.compareTo(n.key);if(c<0)n.left=insert(n.left,k);else if(c>0)n.right=insert(n.right,k);return n;} public boolean contains(E k){Node<E> n=root;while(n!=null){int c=k.compareTo(n.key);if(c==0)return true;n=c<0?n.left:n.right;}return false;} public E findMin(){Node<E> n=root;while(n.left!=null)n=n.left;return n.key;} public E findMax(){Node<E> n=root;while(n.right!=null)n=n.right;return n.key;} public int height(){return height(root);} private int height(Node<E> n){return n==null?-1:1+Math.max(height(n.left),height(n.right));} public int count(){return count(root);} private int count(Node<E> n){return n==null?0:1+count(n.left)+count(n.right);} public int leaves(){return leaves(root);} private int leaves(Node<E> n){return n==null?0:n.left==null&&n.right==null?1:leaves(n.left)+leaves(n.right);} public boolean invariant(){return invariant(root,null,null);} private boolean invariant(Node<E> n,E lo,E hi){if(n==null)return true;if(lo!=null&&n.key.compareTo(lo)<=0)return false;if(hi!=null&&n.key.compareTo(hi)>=0)return false;return invariant(n.left,lo,n.key)&&invariant(n.right,n.key,hi);} public void remove(E k){root=remove(root,k);} private Node<E> remove(Node<E> n,E k){if(n==null)return null;int c=k.compareTo(n.key);if(c<0)n.left=remove(n.left,k);else if(c>0)n.right=remove(n.right,k);else if(n.left!=null&&n.right!=null){Node<E> m=n.right;while(m.left!=null)m=m.left;n.key=m.key;n.right=remove(n.right,n.key);}else n=n.left!=null?n.left:n.right;return n;} public static void run(){BinarySearchTree<Integer> t=new BinarySearchTree<Integer>();for(int x:new int[]{6,3,8,1,4,7,9})t.insert(x);System.out.println("BST contains 4="+t.contains(4)+", min="+t.findMin()+", max="+t.findMax()+", height="+t.height()+", nodes="+t.count()+", leaves="+t.leaves()+", invariant="+t.invariant());t.remove(3);System.out.println("After removing 3, invariant="+t.invariant());System.out.println("Invariant: left keys < node < right keys; operations O(height).\n");} public static void main(String[] args){run();}}
